suppressPackageStartupMessages({library(survey);library(foreign);library(jsonlite)});out<-'analysis/tasks/V3-I01/rev-1/work';b<-readRDS(file.path(out,'prepared.rds'))$base;options(survey.lonely.psu='fail');rr<-list()
for(w in c('weight_mec_18yr','weight_diet14')){z<-b[is.finite(b[[w]])&b[[w]]>0,];d<-svydesign(ids=~SDMVPSU,strata=~SDMVSTRA,weights=as.formula(paste0('~',w)),nest=TRUE,data=z);rr[[w]]<-data.frame(weight=w,n=nrow(z),minimum_age=min(z$RIDAGEYR),maximum_age=max(z$RIDAGEYR),df=degf(d),strata=length(unique(z$SDMVSTRA)),PSU=nrow(unique(z[c('SDMVSTRA','SDMVPSU')])),weight_sum=sum(z[[w]]))};write.csv(do.call(rbind,rr),file.path(out,'design_parent_audit.csv'),row.names=FALSE)
checks<-list();for(cy in sort(unique(b$cycle))[3:9]){f<-list.files(file.path('analysis/data/raw',cy),pattern='^DR2TOT.*\\.xpt$',full.names=TRUE);z<-read.xport(f);i<-match(z$SEQN,b$SEQN);stopifnot(!anyNA(i),all(b$cycle[i]==cy),!anyDuplicated(z$SEQN));j<-is.finite(z$WTDR2D)&z$WTDR2D>0;stopifnot(all(abs(b$weight_diet14[i[j]]-z$WTDR2D[j]/7)<1e-10));checks[[cy]]<-data.frame(cycle=cy,raw_n=nrow(z),positive_weight_parent=sum(j),adult_domain=sum(b$diet_domain&b$cycle==cy),join_verified=TRUE)};write.csv(do.call(rbind,checks),file.path(out,'diet_join_audit.csv'),row.names=FALSE)
obs<-b[!is.na(b$candidate36_observed_items),];write.csv(as.data.frame(table(cycle=obs$cycle,observed_items=obs$candidate36_observed_items)),file.path(out,'observed_item_count_distribution.csv'),row.names=FALSE)
write.csv(data.frame(cycle=sort(unique(obs$cycle)),age50_input=vapply(sort(unique(obs$cycle)),function(cy)sum(obs$cycle==cy),integer(1)),CBC_all4_positive=vapply(sort(unique(obs$cycle)),function(cy)sum(obs$cycle==cy&is.finite(obs$NLR)&obs$NLR>0&is.finite(obs$MLR)&obs$MLR>0&is.finite(obs$SIRI)&obs$SIRI>0&is.finite(obs$SII)&obs$SII>0),integer(1))),file.path(out,'CBC_selection_counts.csv'),row.names=FALSE)
